<script setup lang="ts">type RedirectRow={id:string;source:string;destination:string;statusCode:number;enabled:boolean};definePageMeta({layout:'admin',middleware:'admin'});const {data,refresh}=await useFetch<RedirectRow[]>('/api/admin/redirects');const csrf=useCsrf();const open=ref(false);const edit=ref<RedirectRow|null>(null);const m=reactive({source:'/',destination:'/',statusCode:301 as 301|302,enabled:true});function start(row?:RedirectRow){edit.value=row||null;Object.assign(m,{source:row?.source||'/',destination:row?.destination||'/',statusCode:row?.statusCode||301,enabled:row?.enabled??true});open.value=true}async function save(){await $fetch(edit.value?`/api/admin/redirects/${edit.value.id}`:'/api/admin/redirects',{method:edit.value?'PUT':'POST',headers:csrf.value,body:m});open.value=false;await refresh()}async function remove(r:RedirectRow){await $fetch(`/api/admin/redirects/${r.id}`,{method:'DELETE',headers:csrf.value});await refresh()}</script><template><div><div class="flex justify-between"><h1 class="text-3xl font-semibold">URL 跳转</h1><button class="rounded-full px-5 py-2 text-white" style="background:var(--accent)" @click="start()">新增跳转</button></div><article v-for="r in data||[]" :key="r.id" class="mt-4 flex justify-between border-b py-4"><div><strong>{{r.source}}</strong> → {{r.destination}} <small>{{r.statusCode}} · {{r.enabled?'启用':'停用'}}</small></div><span><button @click="start(r)">编辑</button> <button @click="remove(r)">删除</button></span></article><div v-if="open" class="fixed inset-0 z-50 grid place-items-center bg-black/50 p-4" @click.self="open=false"><form class="w-full max-w-lg rounded-2xl p-6" style="background:var(--surface)" @submit.prevent="save"><h2 class="text-xl font-semibold">{{edit?'编辑':'新增'}}跳转</h2><div class="mt-4 grid gap-3"><input v-model="m.source" required placeholder="旧路径，例如 /old-post" class="rounded border bg-transparent p-2"><input v-model="m.destination" required placeholder="目标路径或 HTTPS URL" class="rounded border bg-transparent p-2"><select v-model.number="m.statusCode" class="rounded border bg-transparent p-2"><option :value="301">301 永久</option><option :value="302">302 临时</option></select><label><input v-model="m.enabled" type="checkbox"> 启用</label></div><div class="mt-5 flex justify-end gap-3"><button type="button" @click="open=false">取消</button><button class="rounded-lg px-4 py-2 text-white" style="background:var(--accent)">保存</button></div></form></div></div></template>
